bounded_host_request.command:
set -euo pipefail
cd "$HOME/Project/Gserver/projects/TGtumbler/GateApp-Bot"
test "$(systemctl --user is-active gace-userbot-verify.service)" = active || exit 60
python3 - <<'PY'
import subprocess,json,sys
p=subprocess.run(["python3","scripts/userbot_topic_audit_client.py","--chat-id","-1003847210571","--topic-id","51"],capture_output=True,text=True,timeout=125)
if p.returncode:sys.exit(61)
a=[json.loads(s.split("=",1)[1]) for s in p.stdout.splitlines() if s.startswith("USERBOT_TOPIC_AUDIT=")]
if len(a)!=1 or len(a[0].get("rows",[]))!=1:sys.exit(62)
row=a[0]["rows"][0]
m=row.get("migration") or {}
if row.get("topic_id")!=51 or m.get("message_id")!=1529:sys.exit(63)
v=m.get("transport")
if v=="INTERNAL_CALLBACK":sys.exit(0)
if v=="REPEATED_START_DEEPLINK":sys.exit(81)
sys.exit(82)
PY
